#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Ohm),
        ElectricReactance::from_ohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Ohm),
        ElectricReactance::from_base(v).as_ohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Nanoohm),
        ElectricReactance::from_nanoohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Nanoohm),
        ElectricReactance::from_base(v).as_nanoohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Microohm),
        ElectricReactance::from_microohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Microohm),
        ElectricReactance::from_base(v).as_microohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Milliohm),
        ElectricReactance::from_milliohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Milliohm),
        ElectricReactance::from_base(v).as_milliohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Kiloohm),
        ElectricReactance::from_kiloohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Kiloohm),
        ElectricReactance::from_base(v).as_kiloohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Megaohm),
        ElectricReactance::from_megaohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Megaohm),
        ElectricReactance::from_base(v).as_megaohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Gigaohm),
        ElectricReactance::from_gigaohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Gigaohm),
        ElectricReactance::from_base(v).as_gigaohms()
    );
    assert_eq!(
        ElectricReactance::new(v, ElectricReactanceUnit::Teraohm),
        ElectricReactance::from_teraohms(v)
    );
    assert_eq!(
        ElectricReactance::from_base(v).convert_to(ElectricReactanceUnit::Teraohm),
        ElectricReactance::from_base(v).as_teraohms()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricReactance; 8] = [
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Ohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Nanoohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Microohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Milliohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Kiloohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Megaohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Gigaohm),
        ElectricReactance::const_new(1234.5, ElectricReactanceUnit::Teraohm),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricReactanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricReactance::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricReactanceUnit::ALL {
            assert_eq!(
                ElectricReactance::const_new(v, unit).as_base().to_bits(),
                ElectricReactance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricReactance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricReactance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricReactanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricReactance::from_base(0.0).auto_unit().unit,
        ElectricReactanceUnit::Ohm
    );
}

